<?php
$pageTitle='Executive overview'; require_once 'includes/auth.php'; require_auth(); $u=current_user();
$stats=[]; $queries=['projects'=>'SELECT COUNT(*) FROM projects WHERE company_id=?','tickets'=>'SELECT COUNT(*) FROM tickets t JOIN projects p ON p.id=t.project_id WHERE p.company_id=?','open'=>'SELECT COUNT(*) FROM tickets t JOIN projects p ON p.id=t.project_id WHERE p.company_id=? AND t.status<>"Closed"','audio'=>'SELECT COUNT(*) FROM audio_logs WHERE company_id=?']; foreach($queries as $k=>$q){$s=$pdo->prepare($q);$s->execute([$u['company_id']]);$stats[$k]=(int)$s->fetchColumn();}
$s=$pdo->prepare('SELECT p.*,COUNT(t.id) ticket_count FROM projects p LEFT JOIN tickets t ON t.project_id=p.id WHERE p.company_id=? GROUP BY p.id ORDER BY p.created_at DESC LIMIT 4');$s->execute([$u['company_id']]);$projects=$s->fetchAll(); require 'includes/header.php';
?><div class="grid grid-4"><?php foreach(['projects'=>'Projects','tickets'=>'Total tickets','open'=>'Open work','audio'=>'Audio logs'] as $k=>$label): ?><div class="card"><div class="stat-label"><?=$label?></div><div class="stat-value"><?=$stats[$k]?></div><div class="stat-foot">Company workspace</div></div><?php endforeach; ?></div><div class="section-head"><h2>Recent projects</h2><a class="button button-light" href="projects.php">View all projects →</a></div><div class="grid grid-2"><?php foreach($projects as $p): ?><article class="card project-card"><div style="display:flex;justify-content:space-between;gap:10px"><h3><?=e($p['name'])?></h3><span class="badge badge-<?=strtolower(str_replace(' ','-',$p['status']))?>"><?=e($p['status'])?></span></div><p><?=e($p['description'])?></p><div class="project-meta"><div><label>Goals</label><?=e($p['goals']?:'Not defined')?></div><div><label>Bottlenecks</label><?=e($p['bottlenecks']?:'None reported')?></div></div><div class="card-actions"><a class="button button-dark" href="tickets.php?project=<?=$p['id']?>">Open project · <?=$p['ticket_count']?> tickets</a></div></article><?php endforeach; ?><?php if(!$projects): ?><div class="card empty">No projects yet. Create the first one from Projects.</div><?php endif; ?></div><?php require 'includes/footer.php';
